<script>document.addEventListener("DOMContentLoaded", function () {

    const banner = document.querySelector(".snn-cookie-banner");
    if (!banner) return;

    const title = banner.querySelector(".snn-preferences-title");
    const text = banner.querySelector(".snn-banner-text");
    const buttons = banner.querySelector(".snn-banner-buttons");
    const acceptBtn = banner.querySelector(".snn-accept");
    const denyBtn = banner.querySelector(".snn-deny");
    const preferencesBtn = banner.querySelector(".snn-preferences");

    /* 1️⃣ Eliminar botón de preferencias */
    if (preferencesBtn) {
        preferencesBtn.remove();
    }

    /* 2️⃣ Cambiar orden (Aceptar primero, luego Rechazar) */
    if (acceptBtn && denyBtn) {
        buttons.insertBefore(denyBtn, acceptBtn);

    }

    /* 3️⃣ Crear wrapper para título + texto */
    if (title && text) {
        const infoWrapper = document.createElement("div");
        infoWrapper.classList.add("snn-banner-info");

        infoWrapper.appendChild(title);
        infoWrapper.appendChild(text);

        banner.insertBefore(infoWrapper, buttons);
    }

});
</script><script>document.addEventListener('DOMContentLoaded', function() {
    
    // Esperar a que Bricks inicialice sus tabs
    setTimeout(function() {
        
        function activateBricksTab(tabSelector, paneSelector) {
            const tab = document.querySelector(tabSelector);
            const pane = document.querySelector(paneSelector);
            
            if (!tab || !pane) {
                console.error('No se encontró la tab o el pane');
                return;
            }

            // Simular click en la tab (esto activa el sistema de Bricks)
            tab.click();
            
            // Scroll después de un momento
            setTimeout(() => {
                const container = document.querySelector('#brxe-nerfpt');
                if (container) {
                    const offset = 100; // Ajusta según tu header
                    const elementPosition = container.getBoundingClientRect().top;
                    const offsetPosition = elementPosition + window.pageYOffset - offset;

                    window.scrollTo({
                        top: offsetPosition,
                        behavior: 'smooth'
                    });
                }
            }, 200);
        }

        function handleHash() {
            const hash = window.location.hash;
            
            console.log('Procesando hash:', hash);
            
            switch(hash) {
                case '#privacidad':
                    console.log('Activando tab de Privacidad');
                    activateBricksTab('#tab-privacidad', '#brxe-kwyysk');
                    break;
                    
                case '#tratamiento':
                    console.log('Activando tab de Tratamiento');
                    activateBricksTab('#tab-tratamiento', '#brxe-nxxodn');
                    break;
                    
                case '#cookies':
                    console.log('Activando tab de Tratamiento y scrolleando a Cookies');
                    activateBricksTab('#tab-tratamiento', '#brxe-nxxodn');
                    setTimeout(() => {
                        const cookiesSection = document.querySelector('#cookies');
                        if (cookiesSection) {
                            cookiesSection.scrollIntoView({ 
                                behavior: 'smooth', 
                                block: 'start' 
                            });
                        }
                    }, 500);
                    break;
            }
        }

        // Ejecutar inmediatamente si ya hay hash
        if (window.location.hash) {
            handleHash();
        }

        // Escuchar cambios de hash
        window.addEventListener('hashchange', handleHash);
        
    }, 500); // Esperar 500ms para que Bricks termine de inicializar
