<script>
/*Comienzo del codigo de boton de accesibilidad*/
	const backToTop = document.querySelector('.containerFlechaAccesibilidad');
    const body = document.documentElement;
    if (localStorage.mode === 'dark') {
        body.classList.add('modo-noche');
    }
    window.toggleLook = function () {
        const currentMode = localStorage.getItem('mode') || 'light';
        const newMode = currentMode === 'light' ? 'dark' : 'light';
        body.classList.toggle('modo-noche', newMode === 'dark');
        localStorage.setItem('mode', newMode);
    };
    // Scripts para aumentar y disminuir letra.
    const getFontSize = () =>
        parseFloat(
            getComputedStyle(document.documentElement).getPropertyValue(
                '--font-size',
            ),
        );
    const storedFontSize = localStorage.getItem('fontSize') || '1';
    const storedZoomCount = parseFloat(localStorage.getItem('zoomCount')) || 0;
    document.documentElement.style.setProperty('--font-size', storedFontSize);
    const fontUp = (element) => {
        element.addEventListener('click', () => {
            let fontSize = getFontSize();
            let zoomCount = parseFloat(localStorage.getItem('zoomCount')) || 0;
            if (zoomCount < 2) {
                fontSize = (fontSize * 1.1).toFixed(1);
                zoomCount++;
                localStorage.setItem('zoomCount', zoomCount);
                localStorage.setItem('fontSize', fontSize);
                document.documentElement.style.setProperty('--font-size', fontSize);
            }
        });
    };
    const fontDown = (element) => {
        element.addEventListener('click', () => {
            let fontSize = getFontSize();
            let zoomCount = parseFloat(localStorage.getItem('zoomCount')) || 0;
            if (zoomCount > -2) {
                fontSize = (fontSize * 0.9).toFixed(1);
                zoomCount--;
                localStorage.setItem('zoomCount', zoomCount);
                localStorage.setItem('fontSize', fontSize);
                document.documentElement.style.setProperty('--font-size', fontSize);
            }
        });
    };
    window.addEventListener('storage', (event) => {
        if (event.key === 'fontSize') {
            // Actualiza el tamaño de fuente en la página actual
            document.documentElement.style.setProperty(
                '--font-size',
                event.newValue,
            );
        }
    });
    addEventListener('keyup', (e) => {
        if (e.key === 'ArrowUp') document.getElementById('font-up').click();
        if (e.key === 'ArrowDown') document.getElementById('font-down').click();
    });
    fontUp(document.getElementById('font-up'));
    fontDown(document.getElementById('font-down'));
    // Función para restablecer el tamaño de fuente a su valor predeterminado
    const resetFontSize = () => {
        const defaultFontSize = '1';
        localStorage.setItem('fontSize', defaultFontSize);
        localStorage.setItem('zoomCount', '0');
        document.documentElement.style.setProperty('--font-size', defaultFontSize);
    };
    window.addEventListener('load', resetFontSize);
    // Fin de Scripts para aumentar y disminuir letra
    buttonUp = document.getElementById('containerFlechaAccesibilidad');
    window.onscroll = function () {
        var scroll = document.documentElement.scrollTop;
        if (scroll > 100) {
            buttonUp.style.transform = 'scale(1)';
        } else if (scroll < 100) {
            buttonUp.style.transform = 'scale(0)';
        }
    };
    document
        .querySelector('.containerFlechaAccesibilidad')
        .addEventListener('click', () => {
            window.scrollTo({
                top: 0,
                behavior: 'smooth',
            });
        });
</script><script>

document.addEventListener('alpine:init', () => {
    Alpine.data('formValidation', () => ({

        formBlocked: false,
        formValid: 'initial',
        messageResponse: '',
        textButton: 'Enviar formulario',
        statusResponse: false,

        // Propiedades para validación de campos
        validateNombre: false,
        alertNombre: '',
        validateApellido: false,
        alertApellido: '',
        validateEmail: false,
        alertEmail: '',
        validateTel: false,
        alertTel: '',
        validateUbicacion: false,
        alertUbicacion: '',
        validatePuesto: false,
        alertPuesto: '',
        
        experiencia: '',
        experienciaLength: 0,
        validateExperiencia: false,
        alertExperiencia: '',
        
        formacion: '',
        formacionLength: 0,
        validateFormacion: false,
        alertFormacion: '',
        
        disponibilidad: '',
        disponibilidadLength: 0,
        validateDisponibilidad: false,
        alertDisponibilidad: '',
        
        fileName: '',
        fileData: null,
        fileError: '',
        isDragging: false,
        
        validateAutorizacion: false,
        alertAutorizacion: '',

        init() {},

        // Validaciones
        validateKey(event) {
            let target = event.target;
            if (target.dataset.validate == 'onlyNumbers') {
                const allowed = ['Backspace', 'Delete', 'ArrowLeft', 'ArrowRight', 'Tab'];
                if (!((event.key >= '0' && event.key <= '9') || allowed.includes(event.key))) {
                    event.preventDefault();
                }
            }
            if (target.dataset.validate == 'onlyLetters') {
                const regex = /^[a-zA-Z\s]$/;
                const allowed = ['Backspace', 'Delete', 'ArrowLeft', 'ArrowRight', 'Tab'];
                if (!regex.test(event.key) && !allowed.includes(event.key)) {
                    event.preventDefault();
                }
            }
            if (target.dataset.validate == 'letters') {
                const regex = /^[a-zA-Z0-9\s-]$/;
                const allowed = ['Backspace', 'Delete', 'ArrowLeft', 'ArrowRight', 'Tab'];
                if (!regex.test(event.key) && !allowed.includes(event.key)) {
                    event.preventDefault();
                }
            }
        },

        validateInputNombre(event) {
            let value = event.target.value.trim();
            this.validateNombre = value !== '';
            this.alertNombre = value !== '' ? 'Nombre válido' : 'Nombre obligatorio';
        },

        validateInputApellido(event) {
            let value = event.target.value.trim();
            this.validateApellido = value !== '';
            this.alertApellido = value !== '' ? 'Apellido válido' : 'Apellido obligatorio';
        },

        validacionEmail(event) {
            const regex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
            let value = event.target.value.trim();
            if (!value) {
                this.validateEmail = false;
                this.alertEmail = 'Campo obligatorio';
            } else {
                this.validateEmail = regex.test(value);
                this.alertEmail = regex.test(value) ? 'Correo válido' : 'Correo inválido';
            }
        },

        validateInputTel(event) {
            let value = event.target.value.trim();
            this.validateTel = value !== '' && !isNaN(value);
            this.alertTel = this.validateTel ? 'Número de celular válido' : 'Número de celular obligatorio';
        },

        validateInputUbicacion(event) {
            let value = event.target.value.trim();
            this.validateUbicacion = value !== '';
            this.alertUbicacion = value !== '' ? 'Ubicación válida' : 'Ubicación actual obligatoria';
        },

        validateInputPuesto(event) {
            let value = event.target.value.trim();
            this.validatePuesto = value !== 'Seleccione' && value !== '';
            this.alertPuesto = this.validatePuesto ? 'Puesto válido' : 'Puesto obligatorio';
        },

        validateInputExperiencia(event) {
            this.experiencia = event.target.value;
            this.experienciaLength = this.experiencia.length;
            this.validateExperiencia = this.experienciaLength > 0;
            this.alertExperiencia = this.validateExperiencia ? 'Experiencia laboral válida' : 'Experiencia laboral obligatoria';
        },

        validateInputFormacion(event) {
            this.formacion = event.target.value;
            this.formacionLength = this.formacion.length;
            this.validateFormacion = this.formacionLength > 0;
            this.alertFormacion = this.validateFormacion ? 'Formación académica válida' : 'Formación académica obligatoria';
        },

        validateInputDisponibilidad(event) {
            this.disponibilidad = event.target.value;
            this.disponibilidadLength = this.disponibilidad.length;
            this.validateDisponibilidad = this.disponibilidadLength > 0;
            this.alertDisponibilidad = this.validateDisponibilidad ? 'Disponibilidad válida' : 'Disponibilidad obligatoria';
        },

        validateInputAutorizacion(event) {
            this.validateAutorizacion = event.target.checked;
            this.alertAutorizacion = this.validateAutorizacion ? '' : 'Debe aceptar la política de privacidad';
        },

        handleFileSelect(event) {
            const file = event.target.files[0];
            if (file) this.validateFile(file);
        },

        handleDrop(event) {
            this.isDragging = false;
            const file = event.dataTransfer.files[0];
            if (file) this.validateFile(file);
        },

        validateFile(file) {
            const allowedTypes = ['application/pdf', 'application/msword', 
                'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
                'image/jpeg', 'image/jpg', 'image/png'];
            
            if (!allowedTypes.includes(file.type)) {
                this.fileError = 'Tipo de archivo no permitido. Solo PDF, DOC, DOCX, JPG, JPEG, PNG';
                this.fileName = '';
                this.fileData = null;
                return;
            }

            if (file.size > 5 * 1024 * 1024) {
                this.fileError = 'El archivo no debe superar 5MB';
                this.fileName = '';
                this.fileData = null;
                return;
            }

            this.fileName = file.name;
            this.fileData = file;
            this.fileError = '';
        },

        get buttonDisabled() {
            return this.validateNombre && this.validateApellido && this.validateEmail &&
                   this.validateTel && this.validateUbicacion && this.validatePuesto &&
                   this.validateExperiencia && this.validateFormacion && 
                   this.validateDisponibilidad && this.validateAutorizacion;
        },

        /**
         * FUNCIÓN CLAVE: Subir archivo a WordPress
         */
        async uploadFileToWordPress(file) {
            const formData = new FormData();
            formData.append('archivo', file);
            
            try {
                const response = await fetch(window.location.origin + '/wp-json/linktic/v1/upload-file', {
                    method: 'POST',
                    body: formData,
                });
                
                const result = await response.json();
                
                if (result.success && result.file && result.file.url) {
                    return result.file.url;
                } else {
                    throw new Error(result.message || 'Error al subir el archivo');
                }
            } catch (error) {
                console.error('Error al subir archivo:', error);
                throw error;
            }
        },

        /**
         * SUBMIT MODIFICADO: Envía a WordPress que hace de proxy
         */
        async submitForm() {
            console.log("Formulario enviado");

            if (!this.buttonDisabled) {
                this.formValid = 'error';
                this.messageResponse = 'Formulario incompleto';
                this.statusResponse = false;
                return;
            }

            this.formValid = 'send';
            this.textButton = 'Cargando';
            this.formBlocked = true;

            try {
                let fileUrl = null;
                
                // PASO 1: Si hay archivo, subirlo a WordPress primero
                if (this.fileData) {
                    this.textButton = 'Subiendo archivo...';
                    fileUrl = await this.uploadFileToWordPress(this.fileData);
                    console.log('Archivo subido a WordPress:', fileUrl);
                }

                // PASO 2: Preparar datos para el webhook
                this.textButton = 'Enviando datos...';
                
                const body = {
                    nombre: document.querySelector('#nombre').value,
                    apellido: document.querySelector('#apellido').value,
                    correo: document.querySelector('#correo').value,
                    telefono: document.querySelector('#prefijo').value + ' ' + document.querySelector('#telefono').value,
                    ubicacion: document.querySelector('#ubicacion').value,
                    puesto: document.querySelector('#puesto').value,
                    experiencia: document.querySelector('#experiencia').value,
                    formacion: document.querySelector('#formacion').value,
                    disponibilidad: document.querySelector('#disponibilidad').value,
                    tratamientoDatosPersonales: document.querySelector('#tratamientoDatosPersonales').checked,
                    autorizacionComunicaciones: document.querySelector('#autorizacionComunicaciones').checked,
                    archivoUrl: fileUrl,
                    archivoNombre: this.fileName || null
                };

                // PASO 3: Enviar a TU API de WordPress (no directamente al webhook)
                const response = await fetch(window.location.origin + '/wp-json/linktic/v1/send-to-webhook', {
                    method: "POST",
                    headers: {
                        "Content-Type": "application/json"
                    },
                    body: JSON.stringify(body),
                });
                
                const result = await response.json();
                
                if (response.ok && result.success) {
                    console.log('Datos enviados exitosamente');
                    window.location.href = '/agradecimiento-contacto';
                } else {
                    throw new Error(result.message || 'Error al enviar los datos');
                }
                
            } catch (error) {
                console.error('Error:', error);
                this.formValid = 'error';
                this.messageResponse = 'Error al enviar los datos. Por favor, intente nuevamente.';
                this.statusResponse = false;
                this.formBlocked = false;
                this.textButton = 'Enviar formulario';
            }
        }
    })); // ← ESTA LLAVE FALTABA

    // Phone selector
    Alpine.data('phoneSelect', () => ({
        open: false,
        selected: { code: '+57', flag: '🇨🇴', name: 'Colombia' },
        countries: [],

        async init() {
            await this.cargarCodigosPaises();
        },

        async cargarCodigosPaises() {
            try {
                const response = await fetch('https://restcountries.com/v3.1/all?fields=name,idd,cca2,translations,flags');
                const data = await response.json();

                this.countries = data
                    .filter(country => country.idd.root)
                    .map(country => ({
                        name: country.translations?.spa?.common || country.name.common,
                        code: country.idd.root + (country.idd.suffixes?.[0] || ''),
                        flag: country.flags.svg || country.flag || '🌍',
                        cca2: country.cca2
                    }))
                    .sort((a, b) => a.name.localeCompare(b.name, 'es'));

                const colombia = this.countries.find(c => c.cca2 === 'CO');
                if (colombia) this.selected = colombia;

            } catch (error) {
                console.error('Error al cargar códigos de países:', error);
                this.countries = [
                    { code: '+57', flag: '🇨🇴', name: 'Colombia', cca2: 'CO' },
                    { code: '+1', flag: '🇺🇸', name: 'Estados Unidos', cca2: 'US' },
                    { code: '+52', flag: '🇲🇽', name: 'México', cca2: 'MX' },
                ];
            }
        },

        selectCountry(country) {
            this.selected = country;
            this.open = false;
        },

        validateKey(e) {
            const allowed = ['Backspace', 'Delete', 'ArrowLeft', 'ArrowRight', 'Tab', ' '];
            if (!((e.key >= '0' && e.key <= '9') || allowed.includes(e.key))) {
                e.preventDefault();
            }
        }
    }));
});</script><link rel="icon" href="#" sizes="32x32">
