			<header id="brx-header"><div id="brxe-xotfgx" data-script-id="xotfgx" class="brxe-code"><script>document.addEventListener('alpine:init', () => {
  Alpine.data('menu', () => ({

    /* ==== ESTADOS DEL MENÚ ==== */
    menuMobile: false,
    openMegaMenu: false,

    // MODIFICADO: incluye búsqueda (?s=) como página NO-home
    scrolled: (
      window.location.pathname === '/' &&
      !window.location.search.includes('s=')
    ) ? false : true,

    megaMenu: '',
    showGradient: false,

    init() {

      // Si está en el HOME y NO es búsqueda
      if (window.location.pathname === '/' && !window.location.search.includes('s=')) {

        const ref = document.getElementById('divReferencia');
        const coords = this.pageCoords(ref);

        this.handleScroll(); // si ya está abajo

        // Scroll listener
        window.addEventListener('scroll', () => {
          this.handleScroll();
        });

        this.refTop = coords.y;
        this.refLeft = coords.x;

        // Recalcular al redimensionar
        window.addEventListener('resize', () => {
          const coords = this.pageCoords(ref);
          this.refTop = coords.y;
          this.refLeft = coords.x;
        });

      } else {
        // Si NO es home o si es búsqueda (?s=)
        this.scrolled = true;
      }

    },

    pageCoords(el) {
      const r = el.getBoundingClientRect();
      return {
        x: r.left + window.scrollX,
        y: r.top + window.scrollY
      };
    },

    handleScroll() {
      this.scrolled = window.scrollY > 50 ? true : false;
    },

