        </div></div></div></div></div></div><div id="brxe-wjnyhu" data-script-id="wjnyhu" class="brxe-code"><script>document.addEventListener('DOMContentLoaded', function () {

    let clients = []
    for(let i = 1; i <= 82; i++){
        let item = { name: `cliente-${i}`, logo: `https://linktic.com/wp-content/uploads/2025/07/cliente-${i}.png` }
        clients.push(item)
    }
    
    const sliderTrack = document.querySelectorAll('.slider-track');

    // Duplicamos los clientes para el efecto infinito (4 veces para asegurar continuidad)
    const duplicatedClients = [...clients, ...clients];
    const duplicatedClientsInvert = [...clients.slice().reverse(), ...clients.slice().reverse()];


    // Generamos los elementos del slider
    duplicatedClients.forEach(client => {
        const clientElement = document.createElement('div');
        clientElement.className = 'px-8 flex items-center justify-center flex-shrink-0';
        clientElement.innerHTML = `
        <img src="${client.logo}" alt="${client.name}" 
        class="h-14 object-contain transition-all duration-300">
        `;
        
        sliderTrack[0].appendChild(clientElement);
    });

    duplicatedClientsInvert.forEach(client => {
        const clientElement = document.createElement('div');
        clientElement.className = 'px-8 flex items-center justify-center flex-shrink-0';
        clientElement.innerHTML = `
        <img src="${client.logo}" alt="${client.name}" 
        class="h-14 object-contain transition-all duration-300">
        `;
        
        sliderTrack[1].appendChild(clientElement);
    });

    // Ajustamos dinámicamente el ancho de los items para mejor responsividad
    function adjustItemWidth() {
        const sliders = document.querySelectorAll('.slider-track');
        sliders.forEach(slider => {
            const items = slider.querySelectorAll('div');
            if (items.length > 0) {
              const itemWidth = items[0].offsetWidth;
              slider.style.setProperty('--item-width', `${itemWidth}px`);
              slider.style.setProperty('--duration', `${(slider.children.length) * 0.2}s`);
              
            }
        });
      
      
    }

    // Ajuste inicial y en redimensionamiento
    adjustItemWidth();
    window.addEventListener('resize', adjustItemWidth);
});</script></div>
