}</style><script>document.addEventListener('alpine:init', () => {

    Alpine.data('cardsProyectosRelevantes', () => ({
      
       autoScrollInterval: null,

        scrollStep: 300,
        scrollDelay: 3000, // cada 3 segundos
        isHovered: false,  // opcional, por si quieres pausar al pasar el mouse


        scrollLeft() {
            this.$refs.sliderContainer.scrollBy({ left: -this.scrollStep, behavior: 'smooth' });
        },
        
        scrollRight() {
            this.$refs.sliderContainer.scrollBy({ left: this.scrollStep, behavior: 'smooth' });
        },
      
      startAutoScroll() {
            this.autoScrollInterval = setInterval(() => {
                if (!this.isHovered) {
                    const container = this.$refs.sliderContainer;
                    const atEnd = container.scrollLeft + container.offsetWidth >= container.scrollWidth;

                    if (atEnd) {
                        // Reinicia al principio
                        container.scrollTo({ left: 0, behavior: 'smooth' });
                    } else {
                        container.scrollBy({ left: this.scrollStep, behavior: 'smooth' });
                    }
                }
            }, this.scrollDelay);
        },
      
      init() {
            this.startAutoScroll();
      }


    }));

});

// 1. Asegúrate de que la configuración de Splide permita clicks
const splideConfig = {
  // ... tu configuración actual
  drag: 'free', // Permite arrastrar pero no bloquea clicks
  flickPower: 300,
  flickMaxPages: 1,
  // Importante: estos valores ayudan a distinguir drag de click
  dragMinThreshold: {
    mouse: 4,
    touch: 10,
  },
};

// 2. Agrega listeners específicos para mobile
document.addEventListener('DOMContentLoaded', function() {
  const cards = document.querySelectorAll('.brxe-zyvkkc a');
  
  cards.forEach(card => {
    // Prevenir que el drag interfiera con el click
    card.addEventListener('click', function(e) {
      // Si el slide está siendo arrastrado, no navegar
      const slider = this.closest('.splide');
      if (slider && slider.classList.contains('is-dragging')) {
        e.preventDefault();
        return false;
      }
    });
    
    // Alternativa: usar touchend para mejor respuesta en mobile
    card.addEventListener('touchend', function(e) {
      const slider = this.closest('.splide');
      if (slider && !slider.classList.contains('is-dragging')) {
        window.location.href = this.href;
      }
    });
  });
});</script></div>
